  return out
}

function parse(src) {
  const toks = tokenize(src)
  let p = 0
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const expect = (v) => { if (!isOp(v)) throw new Bad(); p++ }
  const CMP = ['=', '<>', '<', '<=', '>', '>=']
  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && CMP.includes(toks[p].v)) {
      const op = toks[p++].v
      l = { n: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { n: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { n: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { n: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw new Bad()
    const t = toks[p++]
    if (t.t === 'num') return { n: 'num', v: t.v }
    if (t.t === 'op') {
      if (t.v === '(') { const e = cmp(); expect(')'); return e }
      throw new Bad()
    }
    const nextIs = (v) => isOp(v)
    if (nextIs('(')) {
      p++
      const args = []
      if (!isOp(')')) {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          break
        }
      }
      expect(')')
      return { n: 'call', name: t.v.toUpperCase(), args }
    }
    const u = t.v.toUpperCase()
    if (u === 'TRUE') return { n: 'bool', v: true }
    if (u === 'FALSE') return { n: 'bool', v: false }
    if (nextIs(':')) {
      p++
      if (p >= toks.length || toks[p].t !== 'word') throw new Bad()
      const w2 = toks[p++].v
      return { n: 'range', a: t.v, b: w2 }
    }
    return { n: 'ref', w: t.v }
  }
  const e = cmp()
  if (p !== toks.length) throw new Bad()
  return e
}

const parsed = new Map()
for (const c of sorted) {
  if (c.content[0] === '=') {
    try { parsed.set(c.key, parse(c.content.slice(1))) } catch (e) { if (!(e instanceof Bad)) throw e; parsed.set(c.key, null) }
  }
}

// ---- deps
function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push({ col: c, row: r })
  return out
}
function collect(node, set) {
  switch (node.n) {
    case 'ref': { const a = parseAddr(node.w); if (a) set.set(a.key, a); break }
    case 'range': {
      const rc = rangeCells(node.a, node.b)
      if (rc) for (const q of rc) set.set(keyOf(q.col, q.row), q)
      break
    }
    case 'bin': collect(node.l, set); collect(node.r, set); break
    case 'un': collect(node.e, set); break
    case 'call': node.args.forEach((a) => collect(a, set)); break
  }
}

if (mode === 'deps') {
  let out = ''
  for (const c of sorted) {
    const ast = parsed.get(c.key)
    let line = c.key + ':'
    if (ast) {
      const set = new Map()
      collect(ast, set)
      const list = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
      for (const q of list) line += ' ' + keyOf(q.col, q.row)
    }
    out += line + '\n'
  }
  process.stdout.write(out)
  process.exit(0)
}

// ---- evaluation
const memo = new Map()
const active = new Set()
function cellValue(key) {
  const c = cells.get(key)
  if (!c) return num(0)
  if (memo.has(key)) return memo.get(key)
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  const s = c.content
  if (s[0] === '=') {
    const ast = parsed.get(key)
    v = ast ? evalNode(ast) : err('#ERR!')
  } else if (s === '') v = num(0)
  else if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) v = num(Number(s))
  else if (ERRORS.includes(s)) v = err(s)
  else v = text(s)
  active.delete(key)
  memo.set(key, v)
  return v
}

function toNum(v) {
  if (v.k === 'e') return v
  if (v.k === 'n') return v
  if (v.k === 'b') return num(v.v ? 1 : 0)
  return err('#VALUE!')
}
const fin = (x) => (Number.isFinite(x) ? num(x) : err('#DIV/0!'))
const rank = { n: 0, t: 1, b: 2 }
function cpStr(a, b) {
  const x = Array.from(a), y = Array.from(b)
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}
function compare(a, b) {
  if (a.k !== b.k) return rank[a.k] - rank[b.k]
  if (a.k === 't') return cpStr(a.v, b.v)
  return Number(a.v) - Number(b.v)
}

function expand(node) {
  // returns list of values (range expanded) for a function argument
  if (node.n === 'range') {
    const rc = rangeCells(node.a, node.b)
    if (!rc) return [err('#REF!')]
    rc.sort((x, y) => x.col - y.col || x.row - y.row)
    return rc.map((q) => cellValue(keyOf(q.col, q.row)))
  }
  return [evalNode(node)]
}

function evalNode(node) {
  switch (node.n) {
    case 'num': return num(node.v)
    case 'bool': return bool(node.v)
    case 'ref': { const a = parseAddr(node.w); return a ? cellValue(a.key) : err('#REF!') }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = toNum(evalNode(node.e))
      if (v.k === 'e') return v
      return node.op === '-' ? num(-v.v) : v
    }
    case 'bin': {
      const l = evalNode(node.l)
      const r = evalNode(node.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (CMPOPS.has(node.op)) {
        const d = compare(l, r)
        switch (node.op) {
          case '=': return bool(d === 0)
          case '<>': return bool(d !== 0)
          case '<': return bool(d < 0)
          case '<=': return bool(d <= 0)
          case '>': return bool(d > 0)
          default: return bool(d >= 0)
        }
      }
      const a = toNum(l)
      if (a.k === 'e') return a
      const b = toNum(r)
      if (b.k === 'e') return b
      switch (node.op) {
        case '+': return fin(a.v + b.v)
        case '-': return fin(a.v - b.v)
        case '*': return fin(a.v * b.v)
        case '/': return b.v === 0 ? err('#DIV/0!') : fin(a.v / b.v)
        default: return fin(Math.pow(a.v, b.v))
      }
    }
    case 'call': return evalCall(node)
  }
}
const CMPOPS = new Set(['=', '<>', '<', '<=', '>', '>='])

function evalCall(node) {
  const { name, args } = node
  const n = args.length
  if (name === 'IF') {
    if (n !== 3) return err('#ERR!')
    if (args.some((a) => a.n === 'range')) return err('#ERR!')
    const c = evalNode(args[0])
    if (c.k === 'e') return c
    if (c.k === 't') return err('#VALUE!')
    const truth = c.k === 'b' ? c.v : c.v !== 0
    return evalNode(truth ? args[1] : args[2])
  }
  if (name === 'ABS') {
    if (n !== 1) return err('#ERR!')
    const vs = expand(args[0])
    const e = vs.find((v) => v.k === 'e')
    if (e) return e
    if (vs.length !== 1) return err('#ERR!')
    const v = toNum(vs[0])
    return v.k === 'e' ? v : num(Math.abs(v.v))
  }
  if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
  if (n < 1) return err('#ERR!')
  const vs = []
  for (const a of args) for (const v of expand(a)) vs.push(v)
  const e = vs.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vs.filter((v) => v.k === 'n').length)
  const ns = []
  for (const v of vs) {
    const x = toNum(v)
    if (x.k === 'e') return x
    ns.push(x.v)
  }
  switch (name) {
    case 'SUM': return fin(ns.reduce((s, x) => s + x, 0))
    case 'MIN': return num(ns.reduce((s, x) => Math.min(s, x)))
    case 'MAX': return num(ns.reduce((s, x) => Math.max(s, x)))
    default: return fin(ns.reduce((s, x) => s + x, 0) / ns.length)
  }
}

function show(v) {
  switch (v.k) {
    case 'n': return String(Number(v.v.toPrecision(10)))
    case 'b': return v.v ? 'TRUE' : 'FALSE'
    default: return v.v
  }
}
let out = ''
for (const c of sorted) out += `${c.key}=${show(cellValue(c.key))}\n`
process.stdout.write(out)
